function projectsPage(){return `${heading('Work, with a point of view','Your projects. Your spotlight.','Add the details, images and films behind your work. Choose what leads on the homepage.',`<button class="admin-button" data-action="new-project">${icon('plus')}New project</button>`)}<div class="toolbar"><label class="search">${icon('search')}<input id="project-search" placeholder="Search your projects…" aria-label="Search projects"></label><select id="project-filter" aria-label="Filter projects"><option value="all">All projects</option><option value="featured">Featured work</option><option value="visible">Visible on website</option><option value="hidden">Hidden projects</option></select><span class="pill gray">${workspace.state.projects.length} projects</span></div><section class="admin-panel">${workspace.state.projects.length?`<div class="table-scroll"><table class="project-table"><thead><tr><th>Project</th><th>Status</th><th>Homepage</th><th>Order</th><th>Actions</th></tr></thead><tbody>${workspace.state.projects.slice().sort((a,b)=>a.order-b.order).map(p=>`<tr data-project-row="${E(p.id)}"><td><div class="project-cell">${projectThumb(p)}<div><strong>${E(p.name)}</strong><span>${E(p.category)}</span></div></div></td><td><label class="toggle"><input type="checkbox" data-project-toggle="published" data-id="${E(p.id)}" ${p.published?'checked':''} aria-label="Show ${E(p.name)} on website">${p.published?'Visible':'Hidden'}</label></td><td><label class="toggle"><input type="checkbox" data-project-toggle="featured" data-id="${E(p.id)}" ${p.featured?'checked':''} aria-label="Feature ${E(p.name)} on homepage">Featured</label></td><td>${p.order+1}</td><td class="actions"><button class="icon-button" data-action="edit-project" data-id="${E(p.id)}" aria-label="Edit ${E(p.name)}">${icon('edit')}</button> <button class="icon-button delete" data-action="delete-project" data-id="${E(p.id)}" aria-label="Remove ${E(p.name)}">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('work','Your work deserves a place.','Build a project page with a cover image, video and the story behind the work.','new-project','Create your first project')}</section>`;}
function field(label,path,options={}){
 const {editor:edit=false,type='text',textarea=false,full=false,required=false,max=options.textarea?7000:500,help='',placeholder='',choices=null,array=false}=options;
 let value=getPath(edit?editor:workspace.state,path);if(array)value=(value||[]).join('\n');
 const binding=edit?'data-edit':'data-bind',id=(edit?'edit-':'field-')+path.replaceAll('.','-');
 let control=choices?`<select id="${id}" ${binding}="${path}" ${required?'required':''}>${choices.map(c=>{const val=Array.isArray(c)?c[0]:c,txt=Array.isArray(c)?c[1]:c;return `<option value="${E(val)}" ${String(value)===String(val)?'selected':''}>${E(txt)}</option>`;}).join('')}</select>`:textarea?`<textarea id="${id}" ${binding}="${path}" ${array?'data-array':''} maxlength="${max}" placeholder="${E(placeholder)}" ${required?'required':''}>${E(value)}</textarea>`:`<input id="${id}" ${binding}="${path}" type="${type}" value="${E(value)}" maxlength="${max}" placeholder="${E(placeholder)}" ${required?'required':''} ${type==='number'?'min="0" max="100"':''}>`;
 return `<div class="admin-field ${full?'full':''}"><label for="${id}">${label}${required?' <span>*</span>':''}</label>${control}${help?`<small>${help}</small>`:''}</div>`;
}
function contentPage(){return `${heading('The story you tell','Words with intention.','Shape your homepage, studio story, services and team. Save a draft, then publish when it feels right.')}<div class="content-tabs" role="tablist">${[['homepage','Homepage'],['studio','Studio & founder'],['services','Services'],['team','Team'],['mailbox','Founder note']].map(([id,label])=>`<button role="tab" aria-selected="${contentTab===id}" class="${contentTab===id?'active':''}" data-action="content-tab" data-id="${id}">${label}</button>`).join('')}</div>${contentTab==='homepage'?`<div class="content-split"><div><section class="form-card"><div class="form-card-header"><div><h2>Your first impression.</h2><p>The words that introduce your studio to the world.</p></div></div><div class="admin-form-grid">${field('Intro label','site.heroEyebrow',{full:true,max:160})}${field('Headline · first line','site.headline',{required:true,max:120})}${field('Headline · accent line','site.headlineAccent',{max:120})}${field('Introduction','site.description',{textarea:true,full:true,max:1500})}</div></section><section class="form-card"><div class="form-card-header"><div><h2>Start the next conversation.</h2><p>The call to action near the end of your pages.</p></div></div><div class="admin-form-grid">${field('Headline','site.ctaHeadline',{textarea:true,full:true,max:400})}${field('Supporting text','site.ctaDescription',{textarea:true,full:true,max:1500})}</div></section></div><aside class="content-tip">${icon('content')}<h3>A little less.<br>A little clearer.</h3><p>Keep the headline focused and the introduction human. Line breaks in longer headlines are preserved.</p><p style="margin-top:18px">Use Preview draft after saving to see the whole experience before publishing.</p></aside></div>`:contentTab==='studio'?`<section class="form-card"><div class="form-card-header"><div><h2>The people behind the work.</h2><p>Your studio’s point of view and the founder’s introduction.</p></div></div><div class="admin-form-grid">${field('Studio headline','site.studioTitle',{textarea:true,full:true,max:400})}${field('Studio introduction','site.studioDescription',{textarea:true,full:true,max:4000})}${field('Founder’s name','site.founderName',{required:true,max:100})}${field('Founder’s role','site.founderRole',{max:160})}${field('Founder’s story','site.founderBio',{textarea:true,full:true,max:7000})}</div></section>`:contentTab==='mailbox'?mailboxContentEditor():contentTab==='services'?`<div class="admin-section-head"><div><h2>A connected set of capabilities.</h2><p>Services also appear in the consultation form.</p></div><button class="admin-button secondary" data-action="new-service">${icon('plus')}Add service</button></div><div class="editable-list">${workspace.state.services.map((s,i)=>`<section class="editable-person"><div class="person-topline"><h3>${String(i+1).padStart(2,'0')} / ${E(s.name)}</h3><button class="icon-button delete" data-action="remove-service" data-id="${i}" aria-label="Remove service">${icon('trash')}</button></div><div class="admin-form-grid">${field('Service name',`services.${i}.name`,{required:true,max:120})}${field('Short description',`services.${i}.short`,{max:500})}${field('Service details',`services.${i}.description`,{textarea:true,full:true,max:4000})}${field('Deliverables',`services.${i}.deliverables`,{textarea:true,max:2500})}${field('Capabilities · one per line',`services.${i}.tags`,{textarea:true,array:true})}</div></section>`).join('')}</div>`:`<div class="admin-section-head"><div><h2>The studio collective.</h2><p>Introduce the people who bring your ideas to life.</p></div><button class="admin-button secondary" data-action="new-team">${icon('plus')}Add person</button></div><div class="editable-list">${workspace.state.team.map((p,i)=>`<section class="editable-person"><div class="person-topline"><h3>${E(p.name)}</h3><button class="icon-button delete" data-action="remove-team" data-id="${i}" aria-label="Remove team member">${icon('trash')}</button></div><div class="admin-form-grid">${field('Name',`team.${i}.name`,{required:true,max:120})}${field('Initials',`team.${i}.initials`,{max:8})}${field('Role',`team.${i}.role`,{full:true,max:180})}${field('Introduction',`team.${i}.description`,{textarea:true,full:true,max:1800})}${field('Profile address',`team.${i}.slug`,{full:true,max:90,help:'Used in /teamjob/your-profile-name/. Lowercase letters, numbers and hyphens.'})}${field('Specialisations · one per line',`team.${i}.specialties`,{textarea:true,array:true})}${field('Experience highlights · one per line',`team.${i}.experience`,{textarea:true,array:true})}<label class="toggle" style="grid-column:1/-1"><input type="checkbox" data-bind="team.${i}.experienceIsSample" ${p.experienceIsSample!==false?'checked':''}>These are illustrative sample highlights. Replace them with verified work before unchecking.</label>${mediaField('Profile photograph',`team.${i}.avatar`,false)}<div class="admin-field full"><label for="person-projects-${i}">Associated studio work</label><select id="person-projects-${i}" multiple data-team-projects="${i}" style="min-height:120px">${workspace.state.projects.map(project=>`<option value="${E(project.id)}" ${(p.projects||[]).includes(project.id)?'selected':''}>${E(project.name)}</option>`).join('')}</select><small>Selected projects appear on this person’s public profile.</small></div></div></section>`).join('')}</div>`}`;}
function miniCampaign(o,emptyAction=false){
 const value=o||{title:'Your next announcement starts here.',body:'A launch, a new direction, or news worth sharing. Give it a considered introduction.',eyebrow:'VELORYZ / BROADCASTS',kind:'announcement',animation:'orbit',theme:'ivory'};
 return CampaignDesign.card(value,{compact:true,brandLogo:workspace.state.branding.headerLogo})+(emptyAction?`<button class="mini-cta" data-action="${o?'edit-offer':'new-offer'}" ${o?'data-id="'+E(o.id)+'"':''}>${o?'Edit campaign':'Create a campaign'} ↗</button>`:'');
}

function offersPage(){
 const list=workspace.state.offers.filter(o=>campaignFilter==='all'||(campaignFilter==='pinned'?(o.placement||'popup')==='pinned':o.kind===campaignFilter));
 return `${heading('Studio broadcasts','Good news. A beautiful entrance.','Design an announcement, run an advertisement, or keep an important message pinned above every public page.',`<button class="admin-button" data-action="new-offer">${icon('plus')}New campaign</button>`)}<div class="broadcast-intro">${[['announcement','popup','content','Announce something.','A cinematic popup, branded artwork and useful links.'],['ad','slider','offer','Sliding advertisement','Rotate ads directly below the main navigation.'],['announcement','pinned','publish','Pin the important things.','A compact message above the navigation on every public page.']].map(([kind,placement,ico,title,body])=>`<article>${icon(ico)}<strong>${title}</strong><p>${body}</p><button class="text-link" data-action="new-offer" data-kind="${kind}" data-placement="${placement}">Create ${placement==='pinned'?'pinned message':kind==='ad'?'advertisement':'announcement'} ↗</button></article>`).join('')}</div><div class="campaign-filter-bar" role="group" aria-label="Filter broadcasts">${[['all','All broadcasts'],['announcement','Announcements'],['ad','Advertisements'],['offer','Offers'],['pinned','Pinned messages']].map(([v,l])=>`<button class="${v===campaignFilter?'selected':''}" data-broadcast-filter="${v}" aria-pressed="${v===campaignFilter}">${l}</button>`).join('')}</div>${list.length?`<div class="offers-grid">${list.map(o=>`<article class="offer-card">${miniCampaign(o)}<div class="offer-card-controls"><label class="toggle"><input type="checkbox" data-offer-toggle="${E(o.id)}" ${o.enabled?'checked':''} aria-label="Enable ${E(o.title)}">${E(offerStatus(o))}</label><div class="campaign-actions"><button class="icon-button" data-action="preview-offer" data-id="${E(o.id)}" aria-label="Preview ${E(o.title)}">${icon('eye')}</button><button class="icon-button" data-action="edit-offer" data-id="${E(o.id)}" aria-label="Edit ${E(o.title)}">${icon('edit')}</button><button class="icon-button" data-action="duplicate-offer" data-id="${E(o.id)}" aria-label="Duplicate ${E(o.title)}">${icon('plus')}</button><button class="icon-button delete" data-action="delete-offer" data-id="${E(o.id)}" aria-label="Remove ${E(o.title)}">${icon('trash')}</button></div></div><div class="offer-meta"><span class="campaign-type-badge">${(o.placement||'popup')==='pinned'?'Pinned above navigation':o.placement==='slider'?'Sliding ad beneath navigation':(o.placement||'popup')==='inline'?'In-page advertisement':'Popup + optional ribbon'}</span><span>Priority ${o.priority}</span></div><div class="offer-meta"><span>${o.startAt?compactDate(o.startAt):'Starts when published'}${o.endAt?' → '+compactDate(o.endAt):' · No end date'}</span></div></article>`).join('')}</div>`:`<section class="admin-panel">${empty('offer','A fresh place for your next update.','Choose a campaign type above, add your artwork and links, then preview and publish.','new-offer','Create a campaign')}</section>`}<div class="offer-timing-note">Save draft → Preview draft → Publish site. Popup frequency is configurable; a refresh can show it again within five seconds. Scheduled campaigns start and expire automatically. The highest-priority active pinned message appears across every public page.</div>`;
}

function brandingPage(){const slots=[['headerLogo','Header logo','The main wordmark in your website navigation.'],['footerLogo','Footer logo','The studio identity at the bottom of every page.'],['heroLogo','Hero emblem','Replace the sculptural V with your own transparent emblem.'],['productLogo','VELORI logo','The product identity on the VELORI showcase page.'],['favicon','Browser icon','A square image works best in browser tabs and bookmarks.']];return `${heading('Unmistakably yours','A consistent identity.','Change each logo independently. Upload transparent PNG or WebP assets, or use an existing image from the media library.')}<div class="logo-grid">${slots.map(([key,title,desc])=>`<section class="logo-card"><div class="logo-preview">${workspace.state.branding[key]?`<img src="${E(workspace.state.branding[key])}" alt="${title}">`:`<span class="logo-placeholder">${key==='productLogo'?'velori.':key==='favicon'||key==='heroLogo'?'V':'VELORYZ'}</span>`}</div><div class="logo-card-copy"><h3>${title}</h3><p>${desc}</p><div class="logo-actions"><button class="admin-button secondary" data-action="choose-logo" data-id="${key}">${icon('media')}Choose image</button><button class="admin-button ghost" data-action="reset-logo" data-id="${key}">Use original</button></div></div></section>`).join('')}</div>`;}
function mediaPage(){return `${heading('Your studio assets','A home for the details.','Images, project films, logos and campaign visuals. Uploaded files can be reused across your website.')}<section class="upload-zone">${icon('upload')}<h3>Bring something new into the studio.</h3><p>PNG, JPG, WebP, GIF or AVIF up to 8 MB.<br>MP4 or WebM videos up to 25 MB.</p><button class="admin-button" data-action="upload">${icon('plus')}Upload media</button></section><div id="upload-state"></div>${!mediaLoaded?'<div class="empty-state"><p>Opening your media library…</p></div>':mediaItems.length?`<div class="media-grid">${mediaItems.map(m=>mediaCard(m)).join('')}</div>`:`<section class="admin-panel">${empty('media','Your asset library is ready.','Upload a logo, cover image or short film to get started.','upload','Upload your first file')}</section>`}`;}
function mediaCard(m,picker=false){return `${picker?`<button class="media-picker-button" data-action="pick-media" data-id="${E(m.id)}">`:''}<article class="media-card"><div class="media-thumb">${m.mime.startsWith('image/')?`<img src="${E(m.url)}" alt="${E(m.filename)}" loading="lazy">`:icon('film')}</div><div class="media-card-info"><strong>${E(m.filename)}</strong><small>${m.mime.startsWith('image/')?'Image':'Video'} · ${(m.size/1024/1024).toFixed(2)} MB</small>${picker?'':`<div class="media-card-actions"><button data-action="copy-media" data-id="${E(m.id)}">Copy link</button><a href="${E(m.url)}" target="_blank" rel="noopener">Open ↗</a><button data-action="archive-media" data-id="${E(m.id)}">Archive</button></div>`}</div></article>${picker?'</button>':''}`;}
function historyPage(){return `${heading('Room to evolve','A history worth keeping.','Each publication is saved. Restore a previous version to a draft, review it, then publish when ready.')}<section class="admin-panel">${!historyLoaded?'<div class="empty-state"><p>Opening the version history…</p></div>':historyItems.length?historyItems.map(h=>`<div class="history-item"><span class="history-version">v${h.revision}</span><div class="history-copy"><h3>${E(h.summary)}</h3><p>${friendlyDate(h.created_at)}</p></div>${h.revision===workspace.publishedVersion?'<span class="pill">Current</span>':''}<button class="admin-button secondary" data-action="restore" data-id="${E(h.id)}">Restore draft ${icon('history')}</button></div>`).join(''):empty('history','Your next chapter starts here.','Version history will appear after your first publication.','','')}</section>`;}
function settingsPage(){return `${heading('The practical details','Connected, from the start.','Keep your studio contact information, visual accent and visitor invitation up to date.')}<section class="form-card"><div class="form-card-header"><div><h2>Your studio identity.</h2><p>The name and short label used with your default wordmark.</p></div></div><div class="admin-form-grid">${field('Studio name','site.name',{required:true,max:60})}${field('Wordmark subtitle','site.tagline',{max:100})}${field('Accent colour','site.accent',{type:'color'})}${field('Location','site.location',{max:180})}</div></section><section class="form-card"><div class="form-card-header"><div><h2>Keep the conversation open.</h2><p>Contact changes update consultation drafts, WhatsApp links and email links across the website.</p></div></div><div class="admin-form-grid">${field('Business email','site.email',{type:'email',required:true,max:180})}${field('WhatsApp / phone','site.phone',{required:true,max:20,help:'Country code and digits only. Example: 919955326740.'})}${field('VELORI website','site.productUrl',{full:true,max:2000})}</div></section><section class="form-card"><div class="form-card-header"><div><h2>A considered invitation.</h2><p>Offers take priority over the consultation invitation so visitors see one clear message.</p></div></div><div class="admin-form-grid"><label class="toggle"><input type="checkbox" data-bind="site.consultationEnabled" ${workspace.state.site.consultationEnabled?'checked':''}>Show the consultation invitation on fresh visits</label>${field('Consultation delay · seconds','site.consultationDelay',{type:'number',help:'Between 6 and 60 seconds. Campaign popups always appear within 5 seconds.'})}${mediaField('Studio film','branding.showreel',false,'video')}</div></section><section class="form-card"><div class="form-card-header"><div><h2>Your content, in your hands.</h2><p>Export a backup or import a studio content document. Imported content becomes a draft.</p></div></div><div class="form-actions" style="display:flex;gap:10px;flex-wrap:wrap"><button class="admin-button secondary" data-action="export">${icon('download')}Export content</button><button class="admin-button secondary" data-action="import">${icon('upload')}Import content</button><button class="admin-button danger" data-action="discard">Discard draft changes</button></div></section>`;}
function mediaField(label,path,edit=true,type='image'){const value=getPath(edit?editor:workspace.state,path);return `<div class="admin-field full"><label>${label}</label><input ${edit?'data-edit':'data-bind'}="${path}" data-media-input="${path}" value="${E(value)}" placeholder="Choose a file or paste a media URL"><div class="media-field-preview" data-media-preview="${path}">${value?type==='video'?`<video src="${E(value)}" controls preload="metadata"></video>`:`<img src="${E(value)}" alt="${label} preview">`:icon(type==='video'?'film':'media')}</div><div class="media-field-actions"><button type="button" data-action="choose-editor-media" data-path="${path}" data-context="${edit?'editor':'state'}" data-type="${type}">Choose ${type}</button><button type="button" data-action="clear-editor-media" data-path="${path}" data-context="${edit?'editor':'state'}" data-type="${type}">Remove</button></div></div>`;}
function markDirty(){workspace.dirty=true;const label=$('#workspace-status');if(label){label.textContent='Unsaved changes';label.classList.add('unsaved');}}
async function saveDraft(){
 if(preview){toast('Sign in on the deployed website to save changes.');return false;}
 const result=await api('/api/admin/draft',{method:'PUT',body:JSON.stringify({state:workspace.state,draftVersion:workspace.draftVersion})});workspace.draftVersion=result.draftVersion;workspace.updatedAt=result.updatedAt;workspace.dirty=false;workspace.hasDraft=true;
 const label=$('#workspace-status');if(label){label.textContent='Draft changes saved';label.classList.remove('unsaved');}return true;
}
async function publish(){
 if(busy)return;if(preview){toast('Publishing is available after the owner signs in.');return;}busy=true;updateBusy(true);
 try{if(workspace.dirty)await saveDraft();const data=await api('/api/admin/publish',{method:'POST',body:JSON.stringify({draftVersion:workspace.draftVersion,publishedVersion:workspace.publishedVersion,summary:'Studio website updated'})});workspace.publishedVersion=data.publishedVersion;workspace.updatedAt=data.updatedAt;workspace.hasDraft=false;historyLoaded=false;try{localStorage.setItem('veloryz.publication',String(data.publishedVersion));}catch{}render();toast('Published. Your website now has the latest studio content.');}
 catch(error){toast(error.message);}finally{busy=false;updateBusy(false);}
}
function updateBusy(value){$$('[data-action="save"],[data-action="publish"]').forEach(button=>button.disabled=value);}
function showModal(title,description,content,footer='',size=''){
 const previous=$('.admin-modal-backdrop');if(previous){modalStack.push({element:previous,focus:modalFocus,active:document.activeElement});previous.remove();}
 modalFocus=document.activeElement;$('#admin-modal').innerHTML=`<div class="admin-modal-backdrop"><section class="admin-modal ${size}" role="dialog" aria-modal="true" aria-labelledby="admin-dialog-title" tabindex="-1"><header class="admin-modal-header"><div><h2 id="admin-dialog-title">${title}</h2><p>${description}</p></div><button class="modal-x" data-action="close-modal" aria-label="Close dialog">×</button></header><div class="admin-modal-body">${content}</div>${footer?`<footer class="admin-modal-footer">${footer}</footer>`:''}</section></div>`;
 document.body.style.overflow='hidden';$('#admin-root').inert=true;requestAnimationFrame(()=>$('.admin-modal').focus({preventScroll:true}));
}
function closeModal(){
 $$('.admin-modal video').forEach(v=>v.pause());$('#admin-modal').innerHTML='';
 if(modalStack.length){const old=modalStack.pop();$('#admin-modal').append(old.element);modalFocus=old.focus;if(old.active?.isConnected)old.active.focus({preventScroll:true});return;}
 document.body.style.overflow='';$('#admin-root').inert=false;if(modalFocus?.isConnected)modalFocus.focus({preventScroll:true});editorDirty=false;
}
function confirmAction(title,message,action,label='Continue',publishRemoval=false){
 showModal(title,'A considered next step.',`<p style="font-size:12px;line-height:1.8;color:#87977b">${message}</p>`,`<button class="admin-button secondary" data-action="close-modal">Cancel</button><button class="admin-button" data-action="confirm-action">${label}</button>${publishRemoval&&!preview?'<button class="admin-button" data-action="confirm-publish">Remove &amp; publish site</button>':''}`,'small');confirmAction.callback=action;
}
function openProject(id){
 editorKind='project';editorDirty=false;
 editor=id?structuredClone(workspace.state.projects.find(p=>p.id===id)):{id:'project-'+newItemId(),name:'',category:'',type:'web',status:'In development',year:String(new Date().getFullYear()),description:'',scope:[],approach:'',note:'',published:true,featured:false,order:workspace.state.projects.length,cover:'',video:'',website:''};
 const edit={editor:true};
 showModal(id?'Refine this project.':'Make room for good work.','A clear story, considered visuals and the details behind your work.',`<form id="editor-form" data-editor-form><div class="admin-form-grid">${field('Project name','name',{...edit,required:true,max:120})}${field('Project category','category',{...edit,max:100,placeholder:'e.g. Digital product'})}${field('Work filter','type',{...edit,choices:[['web','Web experience'],['product','Digital product'],['brand','Brand identity'],['motion','Motion & film']]})}${field('Project status','status',{...edit,max:100})}${field('Year / small label','year',{...edit,max:100})}${field('Display order · starts at 0','order',{...edit,type:'number'})}${field('The project story','description',{...edit,textarea:true,full:true,max:7000})}${field('The focus · one item per line','scope',{...edit,textarea:true,array:true})}${field('The approach','approach',{...edit,textarea:true,max:7000})}${mediaField('Cover image','cover')}${mediaField('Project film','video',true,'video')}${field('Project website','website',{...edit,full:true,max:2000,placeholder:'https://your-project.com'})}${field('Project note','note',{...edit,textarea:true,full:true,max:2000})}<label class="toggle"><input type="checkbox" data-edit="published" ${editor.published?'checked':''}>Visible on the website after publishing</label><label class="toggle"><input type="checkbox" data-edit="featured" ${editor.featured?'checked':''}>Highlighted on the homepage</label></div><div id="editor-error"></div></form>`,`<span class="footer-hint">Publishing includes all saved draft changes.</span><button class="admin-button secondary" data-action="close-modal">Cancel</button><button class="admin-button" type="submit" form="editor-form">Save draft</button><button class="admin-button" type="submit" form="editor-form" value="publish">Save &amp; publish site</button>`);
}
function dateInput(value){if(!value)return '';const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function openOfferEditor(id,kind='offer',placement='popup'){
 editorKind='offer';editorDirty=false;
 editor=CampaignDesign.normal(id?structuredClone(workspace.state.offers.find(o=>o.id===id)):{id:'campaign-'+newItemId(),title:'',eyebrow:'A NOTE FROM VELORYZ',body:'',kind,placement,media:'',mediaType:'none',buttonLabel:'Explore the studio',buttonUrl:'/work/',enabled:false,startAt:'',endAt:'',priority:50});
 const edit={editor:true};
 showModal(id?'Refine your broadcast.':'Give your update a good entrance.','All campaigns support your logo, two useful links, a schedule and a considered motion direction.',`<form id="editor-form" data-editor-form><div class="offer-editor-layout"><div class="admin-form-grid">${field('Campaign title','title',{...edit,required:true,full:true,max:160})}${field('Small label','eyebrow',{...edit,full:true,max:100})}${field('Message','body',{...edit,textarea:true,full:true,max:2500})}${field('Campaign type','kind',{...edit,choices:[['offer','Offer'],['announcement','Announcement'],['ad','Advertisement']]})}${field('Where it appears','placement',{...edit,choices:[['popup','Popup + optional bottom ribbon'],['slider','Sliding ad beneath navigation'],['inline','Inside pages / designed card'],['pinned','Pinned above site navigation']]})}${field('Colour direction','theme',{...edit,choices:[['ivory','Warm ivory'],['dark','Charcoal & gold'],['gold','Soft gold']]})}${field('Motion artwork','animation',{...edit,choices:[['orbit','Dimensional orbits'],['ribbon','Sculptural ribbon'],['pulse','Expanding signals']]})}${field('Entrance animation','entrance',{...edit,choices:[['rise','Rise'],['slide','Slide'],['unfold','Unfold'],['fade','Fade']]})}${field('Entrance speed','pace',{...edit,choices:[['quick','Quick'],['standard','Standard'],['slow','Slow']]})}${mediaField('Campaign logo · optional','logo',true,'image')}${field('Logo destination · optional','logoLink',{...edit,max:2000,placeholder:'/ or https://…'})}${field('Media type','mediaType',{...edit,choices:[['none','Original animated artwork'],['image','Image'],['video','Video with playback controls']]})}${mediaField('Campaign visual','media',true,editor.mediaType==='video'?'video':'image')}${field('Primary button label','buttonLabel',{...edit,max:70})}${field('Primary destination','buttonUrl',{...edit,max:2000,placeholder:'/book/ or https://…'})}${field('Secondary link label · optional','secondaryLabel',{...edit,max:70})}${field('Secondary destination · optional','secondaryUrl',{...edit,max:2000,placeholder:'/design/ or https://…'})}${field('Popup frequency','frequency',{...edit,choices:[['refresh','Every full refresh'],['session','Once per browser session'],['day','Once per day']]})}${field('Popup delay','delay',{...edit,choices:[[1,'1 second'],[2,'2 seconds'],[3,'3 seconds'],[4,'4 seconds'],[4.7,'Within 5 seconds'],[5,'5 seconds']]})}${field('Priority','priority',{...edit,choices:[[0,'Low · 0'],[25,'Standard · 25'],[50,'Important · 50'],[75,'High · 75'],[100,'First in line · 100']]})}<div class="admin-field"><label for="offer-start">Starts · optional</label><input id="offer-start" data-edit="startAt" type="datetime-local" value="${dateInput(editor.startAt)}"></div><div class="admin-field"><label for="offer-end">Ends · optional</label><input id="offer-end" data-edit="endAt" type="datetime-local" value="${dateInput(editor.endAt)}"></div><div class="admin-field full campaign-editor-help">Dates use your device’s local time. Leave them empty for immediate publication with no expiry. Popup frequency and delay apply to popups; pinned messages stay across public routes. All popup dialogs can be closed using the keyboard.</div><label class="toggle"><input type="checkbox" data-edit="ribbon" ${editor.ribbon?'checked':''}>Keep popup in the bottom ribbon</label><label class="toggle"><input type="checkbox" data-edit="dismissible" ${editor.dismissible?'checked':''}>Allow dismissing pins / in-page cards</label><label class="toggle full"><input type="checkbox" data-edit="enabled" ${editor.enabled?'checked':''}>Enable when the site is published</label></div><aside class="offer-editor-preview"><p>Live visual preview</p><div id="offer-editor-preview">${miniCampaign(editor)}</div><div class="offer-timing-note">Uploaded media replaces the motion illustration. Your logo and links remain part of the design. Open Preview draft to check the exact public placement.</div></aside></div><div id="editor-error"></div></form>`,`<span class="footer-hint">Publishing includes all saved draft changes.</span><button class="admin-button secondary" data-action="close-modal">Cancel</button><button class="admin-button" type="submit" form="editor-form">Save draft</button><button class="admin-button" type="submit" form="editor-form" value="publish">Save &amp; publish site</button>`);
}

function updateMediaPreview(path,value,type){const input=$(`[data-media-input="${path}"]`);if(input)input.value=value;const el=$(`[data-media-preview="${path}"]`);if(el)el.innerHTML=value?type==='video'?`<video src="${E(value)}" controls preload="metadata"></video>`:`<img src="${E(value)}" alt="Selected media preview">`:icon(type==='video'?'film':'media');}
async function loadMedia(){if(preview){mediaLoaded=true;mediaItems=[];if(section==='media')render();return;}try{const data=await api('/api/admin/media');mediaItems=data.items;mediaLoaded=true;if(section==='media')render();}catch(error){toast(error.message);}}
async function loadHistory(){if(preview){historyLoaded=true;historyItems=[];if(section==='history')render();return;}try{const data=await api('/api/admin/history');historyItems=data.items;historyLoaded=true;if(section==='history')render();}catch(error){toast(error.message);}}
let mediaCallback=null,mediaFilter='image';
async function chooseMedia(callback,type='image'){
 mediaCallback=callback;mediaFilter=type;if(!mediaLoaded)await loadMedia();
 const items=mediaItems.filter(m=>m.mime.startsWith(type+'/'));
 showModal(type==='video'?'Choose a film.':'Choose an image.','Use an existing asset or upload something new.',`<div style="margin-bottom:20px"><button class="admin-button secondary" data-action="picker-upload">${icon('upload')}Upload ${type}</button></div>${items.length?`<div class="media-grid">${items.map(m=>mediaCard(m,true)).join('')}</div>`:empty(type==='video'?'film':'media','A blank canvas, for now.','Upload a file to begin your studio media collection.','','')}`,`<span class="footer-hint">${type==='video'?'MP4 or WebM up to 25 MB.':'PNG, JPG, WebP, GIF or AVIF up to 8 MB.'}</span><button class="admin-button secondary" data-action="close-modal">Cancel</button>`);
}
function filePrompt(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.className='file-input';document.body.append(input);input.addEventListener('change',()=>{const file=input.files?.[0];input.remove();if(file)callback(file);},{once:true});input.click();}
async function uploadFile(file,select=false){
 if(preview){toast('Uploads are available after the owner signs in.');return;}
 const isVideo=file.type.startsWith('video/');if(file.size>(isVideo?25:8)*1024*1024){toast('Keep images under 8 MB and videos under 25 MB.');return;}
 const progress=document.createElement('div');progress.className='upload-progress';progress.textContent='Uploading '+file.name+'…';($('.admin-modal-body')||$('#upload-state')||$('#admin-content')).prepend(progress);
 try{const uploadId=crypto.randomUUID(),chunkSize=2*1024*1024,count=Math.ceil(file.size/chunkSize);for(let index=0;index<count;index++){await api('/api/admin/media/chunk?id='+uploadId+'&index='+index,{method:'POST',body:file.slice(index*chunkSize,(index+1)*chunkSize),headers:{'Content-Type':'application/octet-stream'}});progress.textContent='Uploading '+file.name+'… '+Math.round((index+1)/count*100)+'%';}const item=await api('/api/admin/media',{method:'POST',body:JSON.stringify({uploadId,count,size:file.size,type:file.type,name:file.name})});mediaItems.unshift(item);mediaLoaded=true;if(select&&mediaCallback){const callback=mediaCallback;closeModal();callback(item.url);}else if(section==='media')render();toast('Media uploaded and ready to use.');}
 catch(error){toast(error.message);}finally{progress.remove();}
}
function applyProjectFilter(){const query=($('#project-search')?.value||'').toLowerCase(),filter=$('#project-filter')?.value||'all';$$('[data-project-row]').forEach(row=>{const p=workspace.state.projects.find(p=>p.id===row.dataset.projectRow);row.hidden=!p.name.toLowerCase().includes(query)||(filter==='featured'&&!p.featured)||(filter==='visible'&&!p.published)||(filter==='hidden'&&p.published);});}
document.addEventListener('input',event=>{
 const el=event.target;if(el.matches('[data-bind]')){let value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.hasAttribute('data-array')?el.value.split('\n').filter(Boolean):el.value;setPath(workspace.state,el.dataset.bind,value);markDirty();}
 if(el.matches('[data-edit]')){let value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.hasAttribute('data-array')?el.value.split('\n').filter(Boolean):el.type==='datetime-local'?(el.value?new Date(el.value).toISOString():''):el.value;setPath(editor,el.dataset.edit,value);editorDirty=true;if(el.dataset.edit==='mediaType')$$('[data-path="media"]').forEach(button=>button.dataset.type=value==='video'?'video':'image');if(editorKind==='offer'&&$('#offer-editor-preview'))$('#offer-editor-preview').innerHTML=miniCampaign(editor);}
 if(el.id==='project-search')applyProjectFilter();
});
document.addEventListener('change',event=>{
 const el=event.target;if(el.hasAttribute('data-project-toggle')){const p=workspace.state.projects.find(p=>p.id===el.dataset.id);p[el.dataset.projectToggle]=el.checked;markDirty();}
 if(el.hasAttribute('data-offer-toggle')){workspace.state.offers.find(o=>o.id===el.dataset.offerToggle).enabled=el.checked;markDirty();}
 if(el.id==='enquiry-filter'){enquiryFilter=el.value;enquiryPage=0;enquiryLoaded=false;render();}
 if(el.id==='project-filter')applyProjectFilter();
 if(el.hasAttribute('data-team-projects')){workspace.state.team[Number(el.dataset.teamProjects)].projects=[...el.selectedOptions].map(option=>option.value);markDirty();}
});
document.addEventListener('submit',async event=>{
 if(!event.target.matches('[data-editor-form]'))return;event.preventDefault();if(!event.target.reportValidity())return;
 const submit=event.submitter;if(submit)submit.disabled=true;
 try{
  if(editorKind==='offer'&&editor.startAt&&editor.endAt&&new Date(editor.startAt)>=new Date(editor.endAt))throw new Error('Choose an end time after the start time.');
  const collection=workspace.state[editorKind==='project'?'projects':'offers'],oldIndex=collection.findIndex(item=>item.id===editor.id),oldState=structuredClone(collection);
  if(oldIndex<0)collection.push(structuredClone(editor));else collection[oldIndex]=structuredClone(editor);markDirty();
  try{const saved=await saveDraft();if(!saved&&preview){closeModal();render();toast('Design preview updated. Sign in on the live site to save.');return;}}catch(error){workspace.state[editorKind==='project'?'projects':'offers']=oldState;throw error;}
  closeModal();render();if(submit?.value==='publish'){await publish();return;}toast(editorKind==='project'?'Project saved to draft. Publish when ready.':'Campaign saved to draft. Publish when ready.');
 }catch(error){$('#editor-error').innerHTML=`<div class="dialog-error" role="alert" style="margin-top:20px">${E(error.message)}</div>`;}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-action],.admin-modal-backdrop');if(!button)return;
 if(button.classList.contains('admin-modal-backdrop')){if(event.target===button)closeModal();return;}
 const action=button.dataset.action,id=button.dataset.id;
 try{
  if(action==='enquiry-open'){openEnquiry(id);return;}
  if(action==='enquiry-refresh'){enquiryLoaded=false;render();return;}
  if(action==='enquiry-page'){enquiryPage=Math.max(0,enquiryPage+Number(id));enquiryLoaded=false;render();return;}
  if(action==='enquiry-save'){if(preview){toast('Read-only design preview.');return;}const item=enquiryItems.find(x=>x.id===id);button.disabled=true;try{await api('/api/admin/enquiries/'+id,{method:'PUT',body:JSON.stringify({status:$('#enquiry-status').value,notes:$('#enquiry-notes').value,version:item.version})});closeModal();enquiryLoaded=false;render();toast('Enquiry updated. Send your reply using your contact app.');}finally{button.disabled=false;}return;}
  if(action==='content-audit'){
   if(preview){toast('The content review requires the owner workspace.');return;}
   const report=await api('/api/admin/quality');
   const entries=report.issues.map(issue=>`<li style="margin:12px 0;font-size:13px;line-height:1.6"><strong>${E(issue.severity.toUpperCase())} · ${E(issue.area)}</strong><div>${E(issue.message)}</div></li>`).join('');
   showModal('Website content review','Source-data checks before publishing. External URLs, browser accessibility and live APIs still need separate verification.',`<p role="status">${report.ok?'No blocking data defects.':'Blocking data defects detected.'} ${report.count} review finding(s).</p><ul style="padding-left:20px;margin-top:15px">${entries}</ul>`,`<button type="button" class="admin-button" data-action="close-modal">Close</button>`,'medium');
   return;
  }
  if(action==='reload'){await loadWorkspace();return;}
  if(action==='menu'){$('.sidebar').classList.toggle('open');return;}
  if(action==='close-menu'){$('.sidebar').classList.remove('open');return;}
  if(action==='close-modal'){closeModal();return;}
  if(action==='confirm-action'||action==='confirm-publish'){const callback=confirmAction.callback;closeModal();await callback?.();if(action==='confirm-publish')await publish();return;}
  if(action==='save'){if(busy)return;busy=true;updateBusy(true);try{if(await saveDraft())toast('Draft saved. Your live website is unchanged.');}finally{busy=false;updateBusy(false);}return;}
  if(action==='publish'){await publish();return;}
  if(action==='new-project'||action==='edit-project'){openProject(id);return;}
  if(action==='delete-project'){confirmAction('Remove this project?','It will be removed from your draft. Publish the site to apply the change.',async()=>{workspace.state.projects=workspace.state.projects.filter(p=>p.id!==id);markDirty();render();},'Remove from draft',true);return;}
  if(action==='new-offer'||action==='edit-offer'){openOfferEditor(id,button.dataset.kind||'offer',button.dataset.placement||'popup');return;}
  if(action==='duplicate-offer'){const source=workspace.state.offers.find(o=>o.id===id);workspace.state.offers.push({...structuredClone(source),id:'campaign-'+newItemId(),title:source.title+' (copy)',enabled:false});markDirty();render();toast('Campaign duplicated as a paused draft.');return;}
  if(action==='preview-offer'){const offer=workspace.state.offers.find(o=>o.id===id);showModal('A considered entrance.','Campaign preview · '+offerStatus(offer),miniCampaign(offer)+`<div class="offer-timing-note">Your draft preview shows the chosen popup, in-page, or pinned placement. Logos, links and motion use the same public design components.</div>`,`<button class="admin-button secondary" data-action="close-modal">Close preview</button>`,'medium');return;}
  if(action==='delete-offer'){confirmAction('Remove this campaign?','The campaign will leave your draft. Publish to remove it from the live website.',()=>{workspace.state.offers=workspace.state.offers.filter(o=>o.id!==id);markDirty();render();},'Remove from draft',true);return;}
  if(action==='content-tab'){contentTab=id;render();return;}
  if(action==='new-service'){workspace.state.services.push({name:'New service',short:'',description:'',deliverables:'',tags:[]});markDirty();render();return;}
  if(action==='new-team'){workspace.state.team.push({name:'New team member',initials:'',role:'',description:'',slug:'new-team-'+Date.now(),specialties:[],experience:[],experienceIsSample:true,avatar:'',projects:[]});markDirty();render();return;}
  if(action==='remove-service'||action==='remove-team'){const key=action==='remove-service'?'services':'team';confirmAction('Remove this entry?','This removes the entry from your draft. Publish to apply the change.',()=>{workspace.state[key].splice(Number(id),1);markDirty();render();},'Remove from draft',true);return;}
  if(action==='choose-logo'){await chooseMedia(value=>{workspace.state.branding[id]=value;markDirty();render();},'image');return;}
  if(action==='reset-logo'){workspace.state.branding[id]='';markDirty();render();return;}
  if(action==='choose-editor-media'){const {path,context,type}=button.dataset;await chooseMedia(value=>{setPath(context==='editor'?editor:workspace.state,path,value);if(context==='editor')editorDirty=true;else markDirty();updateMediaPreview(path,value,type);},type);return;}
  if(action==='clear-editor-media'){const {path,context,type}=button.dataset;setPath(context==='editor'?editor:workspace.state,path,'');if(context==='editor')editorDirty=true;else markDirty();updateMediaPreview(path,'',type);return;}
  if(action==='pick-media'){const item=mediaItems.find(m=>m.id===id),callback=mediaCallback;closeModal();callback?.(item.url);return;}
  if(action==='upload'||action==='picker-upload'){filePrompt(action==='picker-upload'?mediaFilter==='image'?'image/png,image/jpeg,image/webp,image/gif,image/avif':'video/mp4,video/webm':'image/png,image/jpeg,image/webp,image/gif,image/avif,video/mp4,video/webm',file=>uploadFile(file,action==='picker-upload'));return;}
  if(action==='copy-media'){const item=mediaItems.find(m=>m.id===id);try{await navigator.clipboard.writeText(location.origin+item.url);toast('Media link copied.');}catch{showModal('Your media link.','Copy this link to reuse the file.',`<input style="width:100%;padding:12px;border:1px solid #dce5d1" readonly value="${E(location.origin+item.url)}">`,'','small');}return;}
  if(action==='archive-media'){confirmAction('Archive this asset?','It will leave the media library. Existing website references and saved versions will keep working.',async()=>{await api('/api/admin/media/'+id,{method:'DELETE'});mediaItems=mediaItems.filter(m=>m.id!==id);render();toast('Asset archived.');},'Archive asset');return;}
  if(action==='restore'){confirmAction('Return to this chapter?','This version will replace your draft. The current live site stays in place until you publish.',async()=>{const data=await api('/api/admin/restore',{method:'POST',body:JSON.stringify({id,draftVersion:workspace.draftVersion})});workspace={...data,dirty:false};render();toast('Version restored to draft. Preview, then publish when ready.');},'Restore to draft');return;}
  if(action==='discard'){confirmAction('Discard your draft changes?','Your draft will return to the current published version.',async()=>{const data=await api('/api/admin/discard',{method:'POST',body:JSON.stringify({draftVersion:workspace.draftVersion})});workspace={...data,dirty:false};render();toast('Draft reset to the published version.');},'Discard draft');return;}
  if(action==='export'){const blob=new Blob([JSON.stringify({format:'veloryz-studio-v1',state:workspace.state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='veloryz-studio-content.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  if(action==='import'){filePrompt('application/json,.json',async file=>{try{const data=JSON.parse(await file.text());if(data.format!=='veloryz-studio-v1'||!data.state)throw new Error('Choose a VELORYZ Studio content backup.');confirmAction('Bring this content into the studio?','The imported document will replace your draft. It will not change the published website until you publish.',async()=>{const before=workspace.state;workspace.state=data.state;try{if(await saveDraft()){render();toast('Content imported to draft.');}}catch(error){workspace.state=before;toast(error.message);}},'Import to draft');}catch(error){toast(error.message);}});return;}
 }catch(error){toast(error.message);}
});
document.addEventListener('keydown',event=>{
 const modal=$('.admin-modal');if(event.key==='Escape'){if(modal)closeModal();else $('.sidebar')?.classList.remove('open');}
 if(event.key==='Tab'&&modal){const items=$$('a[href],button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),video[controls]',modal).filter(el=>el.offsetParent!==null);const first=items[0],last=items.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===modal)){event.preventDefault();first?.focus();}}
 if((event.ctrlKey||event.metaKey)&&event.key==='s'){event.preventDefault();if(workspace&&!busy)saveDraft().then(saved=>saved&&toast('Draft saved.')).catch(error=>toast(error.message));}
});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('beforeunload',event=>{if(workspace?.dirty){event.preventDefault();event.returnValue='';}});
if(window.ADMIN_UNLOCK_PREVIEW)passwordUnlock();else loadWorkspace();

function mailboxContentEditor(){return `<section class="form-card"><div class="form-card-header"><div><h2>A little note, a lot of personality.</h2><p>This message appears as an animated letter beside the tiny mailbox at the bottom of every public page.</p></div></div><div class="admin-form-grid"><label class="toggle" style="grid-column:1/-1"><input type="checkbox" data-bind="site.mailboxEnabled" ${workspace.state.site.mailboxEnabled!==false?'checked':''}>Show the founder’s mailbox</label>${field('Letter title','site.mailboxTitle',{full:true,max:160})}${field('Your note','site.mailboxMessage',{textarea:true,full:true,max:5000,help:'Line breaks are preserved. Keep it personal; this is a little note from your desk.'})}</div></section>`;}

function newItemId(){return crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,12);}

async function loadEnquiries(){
 const sequence=++enquirySequence;enquiryLoading=true;enquiryError='';
 try{
  let data;
  if(preview){const day=new Date(Date.now()+86400000).toISOString().slice(0,10);data={total:1,items:[{id:'00000000-0000-4000-8000-000000000001',reference:'VZ-PREVIEW',name:'Preview Visitor',email:'visitor@example.com',phone:'',service:'Websites & development',budget:'Let’s discuss',preferred_date:day,preferred_time:'11:00 AM – 12:00 PM',company:'Example studio',message:'A sample enquiry to preview the inbox design. No real request or message was sent.',status:'new',notes:'',version:0,created_at:new Date().toISOString(),updated_at:new Date().toISOString()}]};}
  else data=await api('/api/admin/enquiries?status='+encodeURIComponent(enquiryFilter)+'&page='+enquiryPage);
  if(sequence!==enquirySequence)return;enquiryItems=data.items;enquiryTotal=data.total;enquiryLoaded=true;
 }catch(error){if(sequence!==enquirySequence)return;enquiryError=error.message;enquiryLoaded=true;}
 finally{if(sequence===enquirySequence){enquiryLoading=false;if(section==='enquiries')render();}}
}
function enquiriesPage(){return `${heading('Studio operations','Project console','Review design requests, project briefs, customer details and payment discussions.')}<section class="admin-panel"><div class="panel-header"><div><h2>Customer requests</h2><p>Only the studio owner can access these contact details.</p></div><button class="admin-button secondary" data-action="enquiry-refresh">Refresh ↻</button></div><div class="enquiry-toolbar"><label for="enquiry-filter">Show requests</label><select id="enquiry-filter">${['all','new','contacted','confirmed','closed'].map(status=>`<option ${status===enquiryFilter?'selected':''} value="${status}">${status==='all'?'All requests':status[0].toUpperCase()+status.slice(1)}</option>`).join('')}</select><span>${enquiryTotal} request${enquiryTotal===1?'':'s'}</span></div>${enquiryError?`<p class="enquiry-empty" role="alert">${E(enquiryError)} Use Refresh to retry.</p>`:!enquiryLoaded?'<p class="enquiry-empty" role="status">Loading your conversations…</p>':!enquiryItems.length?'<p class="enquiry-empty">A little quiet, for now. New consultation requests will appear here.</p>':`<div class="enquiry-list">${enquiryItems.map(item=>`<button class="enquiry-row" data-action="enquiry-open" data-id="${E(item.id)}"><span class="enquiry-avatar">${E(item.name.slice(0,1))}</span><span class="enquiry-person"><strong>${E(item.name)}</strong><small>${E(item.service)}</small></span><span class="enquiry-schedule">${E(item.preferred_date||item.reference)}<small>${E(item.preferred_time?item.preferred_time+' · IST':item.email)}</small></span><span class="pill ${item.status==='closed'?'gray':''}">${E(item.status)}</span><span class="enquiry-arrow">↗</span></button>`).join('')}</div>`}<div class="enquiry-pagination"><button class="admin-button secondary" data-action="enquiry-page" data-id="-1" ${enquiryPage===0?'disabled':''}>← Previous</button><span>Page ${enquiryPage+1}</span><button class="admin-button secondary" data-action="enquiry-page" data-id="1" ${(enquiryPage+1)*25>=enquiryTotal?'disabled':''}>Next →</button></div></section>`;}
function openEnquiry(id){
 const item=enquiryItems.find(x=>x.id===id);if(!item)return;
 const subject=(item.status==='confirmed'?'Consultation confirmation':'Your studio enquiry')+' · '+item.reference;
 const message=`Hi ${item.name},\n\nThank you for your enquiry (${item.reference}).\nPreferred consultation: ${item.preferred_date}, ${item.preferred_time} IST.\n\n${item.status==='confirmed'?'Your consultation time is confirmed.':'Let’s discuss the next step for your project.'}\n\nVELORYZ Studio`;
 const email='mailto:'+encodeURIComponent(item.email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(message);
 const phone=item.phone.replace(/\D/g,'');
 showModal(E(item.name),E(item.reference)+' · Received '+E(friendlyDate(item.created_at)),`<div class="enquiry-detail-grid"><div><span>Email</span><a href="mailto:${E(item.email)}">${E(item.email)}</a></div><div><span>Phone / WhatsApp</span><strong>${E(item.phone||'Not provided')}</strong></div><div><span>Service</span><strong>${E(item.service)}</strong></div><div><span>Budget</span><strong>${E(item.budget||'Let’s discuss')}</strong></div><div><span>Preferred consultation · IST</span><strong>${E(item.preferred_date||'To be arranged')}<br>${E(item.preferred_time)}</strong></div><div><span>Company / website</span><strong>${E(item.company||'Not provided')}</strong></div></div><div class="enquiry-message"><span>THE PROJECT</span><p>${E(item.message).replace(/\n/g,'<br>')}</p></div><section data-request-history><h3>Request activity</h3><p>Loading activity…</p></section><div class="enquiry-edit"><label for="enquiry-status">Request status</label><select id="enquiry-status">${['new','contacted','confirmed','closed'].map(status=>`<option ${status===item.status?'selected':''} value="${status}">${status}</option>`).join('')}</select><label for="enquiry-notes">Private studio notes</label><textarea id="enquiry-notes" maxlength="3000" rows="4">${E(item.notes)}</textarea><p>Confirming reserves the preferred time and prevents a second confirmation for that slot. Send your reply separately using the contact drafts below.</p></div><div class="enquiry-reply"><a class="admin-button secondary" href="${E(email)}">Prepare email reply ↗</a>${phone?`<a class="admin-button secondary" href="https://wa.me/${phone}?text=${encodeURIComponent(message)}" target="_blank" rel="noopener">Prepare WhatsApp reply ↗</a>`:''}</div>`,`<span class="footer-hint">Changes apply to this inbox immediately.</span><button class="admin-button" data-action="enquiry-save" data-id="${E(id)}">Save request ${icon('check')}</button>`);
 const history=document.querySelector('[data-request-history]');
 api('/api/admin/enquiries/'+encodeURIComponent(id)+'/activity').then(({events})=>{
  if(!history.isConnected)return;
  history.innerHTML='<h3>Request activity</h3>'+events.map(e=>'<p><strong>'+E(e.status)+'</strong> · '+E(new Date(e.recorded_at).toLocaleString('en-IN'))+'<br>'+E(e.notes||'Request received')+'</p>').join('');
 }).catch(()=>{history.querySelector('p').textContent='Activity could not be loaded.';});
}

document.addEventListener('click',event=>{const b=event.target.closest('[data-broadcast-filter]');if(b){campaignFilter=b.dataset.broadcastFilter;render();}});
